from fastapi import FastAPI, HTTPException, Query
from pydantic import BaseModel, Field
import sqlite3
import uvicorn
from contextlib import contextmanager
from typing import Optional

app = FastAPI(title="CommunityHealthSurvey", version="1.0.0")

DATABASE = "db.sqlite3"

def get_db():
    conn = sqlite3.connect(DATABASE, check_same_thread=False)
    conn.execute("PRAGMA journal_mode=WAL")
    conn.row_factory = sqlite3.Row
    return conn

@contextmanager
def db_connection():
    conn = get_db()
    try:
        yield conn
    finally:
        conn.close()

def init_db():
    with db_connection() as conn:
        conn.execute("""
            CREATE TABLE IF NOT EXISTS submissions (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                age INTEGER NOT NULL,
                weight REAL NOT NULL,
                smokingStatus INTEGER NOT NULL,
                city TEXT NOT NULL
            )
        """)
        conn.commit()

@app.on_event("startup")
def startup():
    init_db()

class HealthMetrics(BaseModel):
    age: int = Field(..., ge=0)
    weight: float = Field(..., ge=0)
    smokingStatus: bool
    city: str

class CityStatistics(BaseModel):
    averageWeight: float
    smokingRate: float

@app.post("/submissions", status_code=201)
def submit_health_metrics(metrics: HealthMetrics):
    if not metrics.city.strip():
        raise HTTPException(status_code=400, detail="City must not be empty")
    try:
        with db_connection() as conn:
            conn.execute(
                "INSERT INTO submissions (age, weight, smokingStatus, city) VALUES (?, ?, ?, ?)",
                (metrics.age, metrics.weight, int(metrics.smokingStatus), metrics.city.strip())
            )
            conn.commit()
    except Exception:
        raise HTTPException(status_code=500, detail="Database error")
    return {"message": "Submission recorded successfully"}

@app.get("/statistics", response_model=CityStatistics)
def get_city_statistics(city: str = Query(..., min_length=1)):
    if not city.strip():
        raise HTTPException(status_code=400, detail="City must not be empty")
    try:
        with db_connection() as conn:
            cursor = conn.execute(
                "SELECT COALESCE(AVG(weight), 0) AS avg_weight, COALESCE(AVG(smokingStatus), 0) AS smoking_rate FROM submissions WHERE city = ?",
                (city.strip(),)
            )
            row = cursor.fetchone()
            avg_weight = float(row["avg_weight"])
            smoking_rate = float(row["smoking_rate"])
    except Exception:
        raise HTTPException(status_code=500, detail="Database error")
    return {"averageWeight": avg_weight, "smokingRate": smoking_rate}

if __name__ == "__main__":
    uvicorn.run(app, host="0.0.0.0", port=5000)
